// Extract video ID from any YouTube URL format
const body = $input.first().json.body || $input.first().json;
const url = body.url;

if (!url) throw new Error('No URL provided. Send a POST body like: {"url": "https://youtube.com/watch?v=..."}');

let videoId = '';

if (url.includes('v=')) {
  videoId = url.split('v=')[1].split('&')[0];
} else if (url.includes('youtu.be/')) {
  videoId = url.split('youtu.be/')[1].split('?')[0];
} else if (url.includes('youtube.com/shorts/')) {
  videoId = url.split('shorts/')[1].split('?')[0];
} else if (url.includes('youtube.com/embed/')) {
  videoId = url.split('embed/')[1].split('?')[0];
}

if (!videoId) throw new Error('Could not extract video ID from: ' + url);

return [{ json: { videoId, originalUrl: url } }];

// Merge title + transcript data
const titleData = $('Get Video Title').item.json;
const transcriptData = $('Fetch Transcript').item.json;
const videoId = $('Extract Video ID').item.json.videoId;

const title = titleData.title || ('Video_' + videoId);

// Parse YouTube's json3 caption format
const events = transcriptData.events || [];

if (events.length === 0) {
  throw new Error('No transcript found for this video. It may not have captions enabled.');
}

// Combine all caption segments into clean text
const lines = [];
for (const event of events) {
  if (!event.segs) continue;
  const text = event.segs.map(s => s.utf8 || '').join('').trim();
  if (text && text !== '\n') {
    lines.push(text.replace(/\n/g, ' '));
  }
}

// Group into paragraphs (every ~8 lines)
const paragraphs = [];
for (let i = 0; i < lines.length; i += 8) {
  paragraphs.push(lines.slice(i, i + 8).join(' '));
}

const cleanTranscript = `Title: ${title}\nVideo ID: ${videoId}\nSource: https://www.youtube.com/watch?v=${videoId}\n\n---\n\n${paragraphs.join('\n\n')}`;

// Sanitize title for use as filename
const safeTitle = title.replace(/[^a-zA-Z0-9 _-]/g, '').replace(/\s+/g, '_').substring(0, 80);
const fileName = safeTitle + '.txt';

return [{ json: { cleanTranscript, fileName, title, videoId } }];
